package main

import "github.com/egoist/mygo/ui"

// lucide creates a 24x24 Lucide SVG icon rendered in currentColor.
func lucide(shapes string) *ui.SVG {
	return ui.MustParseSVG([]byte(`<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">` + shapes + `</svg>`))
}

// winui3 creates a 10x10 WinUI 3 (Segoe Fluent Icons) caption button glyph with a crisp 1px hairline stroke.
func winui3(shapes string) *ui.SVG {
	return ui.MustParseSVG([]byte(`<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1" stroke-linecap="square" stroke-linejoin="miter">` + shapes + `</svg>`))
}

